css:
.ss-tbl{display:flex;flex-direction:column;border:1px solid var(--line);border-bottom:none}
.ss-tbl__hr,.ss-tbl__r{display:grid;grid-template-columns:var(--ss-tbl-cols, 1fr 1.3fr);gap:0}
.ss-tbl__hr{background:var(--ink)}
.ss-tbl__h{font:700 10px/1.4 var(--font-body);letter-spacing:.12em;text-transform:uppercase;color:#fff;padding:14px 16px}
.ss-tbl__r{border-bottom:1px solid var(--line)}
.ss-tbl__a{font-size:14px;line-height:1.6;font-weight:700;color:var(--ink);padding:16px;border-right:1px solid var(--line)}
.ss-tbl__b{font-size:14px;line-height:1.6;color:var(--body-text, #3f3f3f);padding:16px}
@media (max-width:640px){.ss-tbl__hr,.ss-tbl__r{grid-template-columns:1fr}.ss-tbl__a{border-right:0;border-bottom:1px solid var(--line)}}
@media (max-width:640px){.ss-tbl__h{font-size:12px}}
